namespace ghidra.framework.main.projectdata.actions;





using docking.widgets.tree;
using ghidra.framework.main.datatable;

public abstract class ProjectDataCopyCutBaseAction : ProjectTreeAction {

	public ProjectDataCopyCutBaseAction(string name, string owner) : base(name, owner)
    {
	}

	/**
	 * Removes any path that is a descendant of a path in the selection.
	 * @param paths selected paths
	 * @return paths that do not have any descendants
	 */
	protected TreePath[] adjustSelectionPaths(TreePath[] paths) {
		HashSet<GTreeNode> set = new();
		foreach (TreePath treePath in paths) {
			set.add((GTreeNode) treePath.getLastPathComponent());
		}
		HashSet<GTreeNode> removeSet = new();
		foreach (GTreeNode node in set) {
			if (anyParentsInSet(set, node)) {
				removeSet.add(node);
			}
		}
		set.removeAll(removeSet);
		TreePath[] newPaths = new TreePath[set.size()];
		int index = 0;
		foreach (GTreeNode node in set) {
			newPaths[index++] = node.getTreePath();
		}
		return newPaths;
	}

	private bool anyParentsInSet(HashSet<GTreeNode> set, GTreeNode node) {
		GTreeNode parent = node.getParent();
		if (parent == null) {
			return false;
		}
		if (set.contains(parent)) {
			return true;
		}
		return anyParentsInSet(set, parent);
	}

}
